def fix(df):
    active = df['Usage_kWh']
    pf = df['Lagging_Current_Power_Factor']
    reactive = np.abs(active) * np.sqrt(np.maximum((100.0 / pf) ** 2 - 1.0, 0.0))
    return reactive.replace([np.inf, -np.inf], 0.0).fillna(0.0)

def fix(df):
    active = df['Usage_kWh']
    reactive = df['Lagging_Current_Reactive_Power_kVarh']
    denominator = np.sqrt(active * active + reactive * reactive)
    result = 100.0 * active / denominator
    return result.replace([np.inf, -np.inf], np.nan).fillna(0.0)

def fix(df):
    active = df['Usage_kWh']
    reactive = df['Leading_Current_Reactive_Power_kVarh']
    magnitude = np.sqrt(active * active + reactive * reactive)
    result = 100.0 * active / magnitude
    return result.replace([np.inf, -np.inf], np.nan).fillna(100.0)
